Bash(powershell -NoProfile -Command '
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class Native {
    [DllImport\("kernel32.dll", SetLastError=true, CharSet=CharSet.Auto\)]
    public static extern uint FormatMessage\(uint dwFlags, IntPtr lpSource, uint dwMessageId, uint dwLanguageId, System.Text.StringBuilder lpBuffer, uint nSize, IntPtr Arguments\);
    [DllImport\("kernel32.dll"\)]
    public static extern IntPtr LoadLibrary\(string lpFileName\);
}
"@
$h = [Native]::LoadLibrary\("ntdll.dll"\)
$sb = New-Object System.Text.StringBuilder 512
$flags = 0x00000800 -bor 0x00001000 -bor 0x00000200
$r = [Native]::FormatMessage\($flags, $h, 0x0000087D, 0, $sb, 512, [IntPtr]::Zero\)
"result=$r msg=$\($sb.ToString\(\)\)"
')

Bash(powershell -NoProfile -Command "
\\$addr = 0x00007FF940A05369
Get-Process -Id \\$PID | Select-Object -ExpandProperty Modules | ForEach-Object {
  \\$base = \\$_.BaseAddress.ToInt64\(\)
  \\$end = \\$base + \\$_.ModuleMemorySize
  if \(\\$addr -ge \\$base -and \\$addr -lt \\$end\) {
    Write-Output \(\\"MATCH: \\" + \\$_.ModuleName + \\" base=0x\\" + \\$base.ToString\('X'\) + \\" end=0x\\" + \\$end.ToString\('X'\)\)
  }
}
")

